"""API Endpoint Permission Canonicalizer.

Reads /app/input.txt and writes the canonical permission configuration
to /app/output.txt.
"""

import re

METHODS = {'GET', 'POST', 'PUT', 'DELETE', 'PATCH'}
PERMISSIONS = {'ALLOW', 'DENY'}

VAR_PATTERN = re.compile(r'\{([A-Za-z0-9_-]+)\}')


def normalize_path(path):
    """Replace all valid {variable_name} patterns with {var}."""
    return VAR_PATTERN.sub('{var}', path)


def split_sections(text):
    """Split the input text into up to 3 sections separated by empty lines."""
    lines = text.split('\n')
    sections = []
    current = []
    for line in lines:
        if line.strip() == '':
            if current:
                sections.append(current)
                current = []
        else:
            current.append(line)
    if current:
        sections.append(current)
    # Pad to three sections
    while len(sections) < 3:
        sections.append([])
    return sections[:3]


def parse_endpoints(lines):
    """Parse ENDPOINTS section with hard cutoff on malformed lines.

    Returns list of dicts with keys:
      path, norm_path, method, role, permission, index
    """
    endpoints = []
    for line in lines:
        fields = line.split()
        if len(fields) != 4:
            break
        path, method, role, permission = fields
        if path.strip() == '':
            break
        method = method.upper()
        if method not in METHODS:
            break
        permission = permission.upper()
        if permission not in PERMISSIONS:
            break
        if role.strip() == '':
            break
        endpoints.append({
            'path': path,
            'norm_path': normalize_path(path),
            'method': method,
            'role': role,
            'permission': permission,
            'index': len(endpoints),
        })
    return endpoints


def parse_base_exclude(lines):
    """Parse BASE/EXCLUDE section.

    Returns (base, excluded_roles).
    """
    base = None
    excluded = set()
    for line in lines:
        fields = line.split()
        if not fields:
            continue
        if fields[0] == 'base':
            if len(fields) >= 2:
                base = fields[1]
        elif fields[0] == 'exclude':
            for role in fields[1:]:
                excluded.add(role)
    return base, excluded


def parse_plan(lines):
    """Parse PLAN section with hard cutoff on malformed lines.

    Returns list of (path, method) tuples.
    """
    plan = []
    for line in lines:
        fields = line.split()
        if len(fields) != 2:
            break
        path, method = fields
        if path.strip() == '':
            break
        method = method.upper()
        if method not in METHODS:
            break
        plan.append((path, method))
    return plan


def main():
    with open('/app/input.txt', 'r') as f:
        text = f.read()

    ep_lines, be_lines, plan_lines = split_sections(text)

    endpoints = parse_endpoints(ep_lines)
    base, excluded = parse_base_exclude(be_lines)
    plan = parse_plan(plan_lines)

    # Base prefix filter
    if base is not None:
        eligible = [e for e in endpoints if e['path'].startswith(base)]
    else:
        eligible = list(endpoints)

    # Group eligible endpoints by normalized path
    paths_by_norm = {}
    for e in eligible:
        paths_by_norm.setdefault(e['norm_path'], []).append(e)

    # Paths that have at least one non-excluded-role endpoint
    non_excluded_paths = set()
    for norm_path, eps in paths_by_norm.items():
        if any(e['role'] not in excluded for e in eps):
            non_excluded_paths.add(norm_path)

    # Determine which normalized paths are "requested"
    requested = set()
    for path, method in plan:
        requested.add(normalize_path(path))

    # Parent path resolution: include parent normalized paths of requested
    # paths that have at least one eligible endpoint (after base/exclude filter)
    # and are not the same as the endpoint path.
    all_norm_paths = set(paths_by_norm.keys())
    included_paths = set(requested)
    for rp in requested:
        for candidate in all_norm_paths:
            if candidate == rp:
                continue
            if rp.startswith(candidate):
                included_paths.add(candidate)

    # Special case: if a parent path has endpoints only for excluded roles,
    # but those endpoints are needed for inheritance resolution, include them
    # ONLY if they are the only endpoints for that parent path AND the parent
    # path is needed for inheritance.
    # (A path "needed for inheritance" = it is a proper parent of a requested
    # path, i.e., it is in included_paths but not in requested.)
    for norm_path in included_paths - requested:
        if norm_path in paths_by_norm:
            eps = paths_by_norm[norm_path]
            # All endpoints for this path are for excluded roles
            if all(e['role'] in excluded for e in eps):
                # They are the only endpoints for that parent path (by
                # definition, all endpoints for the path are excluded-role
                # endpoints) and the path is needed for inheritance.
                pass  # path stays included

    # Build output endpoints
    output = []
    for norm_path in included_paths:
        eps = paths_by_norm.get(norm_path, [])
        for e in eps:
            if e['role'] in excluded:
                # Exclude unless the special inheritance case applies:
                # the path is needed for inheritance (a proper parent of a
                # requested path) and all endpoints for that path are for
                # excluded roles.
                if norm_path not in requested and \
                        all(x['role'] in excluded for x in eps):
                    output.append(e)
                # When PLAN is empty, excluded roles are always filtered out;
                # requested == included_paths in that case, so the condition
                # above is false.
            else:
                output.append(e)

    # Deduplicate on (path, method, role) using original path names;
    # keep first encountered by ENDPOINTS input order.
    seen = set()
    deduped = []
    for e in sorted(output, key=lambda e: e['index']):
        key = (e['path'], e['method'], e['role'])
        if key in seen:
            continue
        seen.add(key)
        deduped.append(e)

    # Path specificity ordering
    def sort_key(e):
        n_segments = len([s for s in e['norm_path'].split('/') if s])
        return (-n_segments, e['method'], e['role'], 0 if e['permission'] == 'ALLOW' else 1)

    deduped.sort(key=sort_key)

    if deduped:
        out = ''.join('{} {} {} {}\n'.format(
            e['path'], e['method'], e['role'], e['permission'])
            for e in deduped)
    else:
        out = '\n'

    with open('/app/output.txt', 'w') as f:
        f.write(out)


if __name__ == '__main__':
    main()
